// SQL generated by scripts/simulations/publication-tool.mjs on an isolated Postgres: staging twice inserts once,
// activation makes 2027 and 2028 current together, rollback withdraws, and a Brazilian publication never changes.
// Run: node supabase/tests/publication-tool.database.test.mjs   (needs Docker and a built @gaiapus/contracts)
import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';
import { activateSql, loadPublication, metadataSql, rollbackSql } from '../../scripts/simulations/publication-tool.mjs';

const container = 'gaiapus-sim-policy-test-20261115';
const docker = (...args) => execFileSync('docker', args, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] }).trim();
let exists = true;
try { docker('inspect', container); } catch { exists = false; }
if (!exists) docker('run', '-d', '--name', container, '--label', 'gaiapus.purpose=isolated-policy-test', '-e', 'POSTGRES_PASSWORD=isolated-test-only', '-e', 'POSTGRES_DB=gaiapus_test', 'postgres:17');
if (docker('inspect', '--format', '{{.State.Running}}', container) !== 'true') docker('start', container);
assert.equal(docker('inspect', '--format', '{{index .Config.Labels "gaiapus.purpose"}}', container), 'isolated-policy-test', 'Only the dedicated isolated test database may be reset');
for (let i = 0; i < 60; i++) { try { docker('exec', container, 'pg_isready', '-U', 'postgres', '-d', 'gaiapus_test'); break; } catch { execFileSync(process.platform === 'win32' ? 'powershell' : 'sleep', process.platform === 'win32' ? ['-Command', 'Start-Sleep -Seconds 1'] : ['1']); } }
const sqlRaw = input => execFileSync('docker', ['exec', '-i', container, 'psql', '-X', '-qAt', '-v', 'ON_ERROR_STOP=1', '-U', 'postgres', '-d', 'gaiapus_test'], { input, encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'], maxBuffer: 64 * 1024 * 1024 });
const sql = input => sqlRaw(input).trim();
sql(`drop schema if exists public cascade; create schema public; drop schema if exists app_private cascade; drop schema if exists auth cascade; create schema auth;
do $$ begin if not exists(select from pg_roles where rolname='anon') then create role anon nologin; end if;
if not exists(select from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
if not exists(select from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if; end $$;
grant usage on schema public, auth to anon, authenticated, service_role;
create table auth.users(id uuid primary key, email_confirmed_at timestamptz);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select jsonb_build_object('email_verified',true) $$;`);
for (const m of readdirSync(new URL('../migrations/', import.meta.url)).filter(f => f.endsWith('.sql')).sort()) sql(readFileSync(new URL(`../migrations/${m}`, import.meta.url), 'utf8'));
const anon = q => sqlRaw(`begin; set local role anon; ${q}; rollback;`).trim();
const counts = () => sql(`select (select count(*) from public.simulation_runs)||','||(select count(*) from public.simulation_artifacts)||','||(select count(*) from public.regional_simulation_publications)||','||(select count(*) from public.simulation_publication_batches)`);

// Brazil as today: one current publication without a batch.
sql(`insert into public.simulation_runs(id,run_key,kind,location_id,plan_id,crops,harvest_years,as_of,issued_at,identity_sha256,contract,execution_status)
  values ('10000000-0000-4000-8000-000000000001','sim_aaaaaaaaaaaaaaaaaaaaaaaa','regional','BR:ibge:5107925','soy>maize2','{soy,maize2}','{2027,2028}','2026-08-31T23:59Z','2026-11-15T12:00Z','${'a'.repeat(64)}','future-simulation-run.v1','succeeded');
 insert into public.regional_simulation_publications(run_id,location_id,plan_id,harvest_years,publication_version,is_current,sanitized)
  values ('10000000-0000-4000-8000-000000000001','BR:ibge:5107925','soy>maize2','{2027,2028}','sim_aaaaaaaaaaaaaaaaaaaaaaaa',true,true);`);
const brazil = () => sql(`select md5(string_agg(p.run_id::text||p.is_current::text||coalesce(p.batch_id::text,'-'), ',' order by p.run_id)) from public.regional_simulation_publications p where p.location_id like 'BR:%'`);
const before = brazil();

const pub = loadPublication(fileURLToPath(new URL('../../packages/contracts/fixtures/us-simulation-v2/', import.meta.url)));
const staging = metadataSql(pub);
sql(staging);
assert.equal(counts(), '6,10,6,1');
assert.equal(anon("select count(*) from simulation_runs where location_id like 'US:%'"), '0', 'staged runs are invisible');
sql(staging); // retried import
assert.equal(counts(), '6,10,6,1', 'second application inserts nothing');
assert.equal(sql(`select count(*) from public.simulation_artifacts where storage_path like '${pub.prefix}/runs/sim_%/%/%' and storage_bucket='simulation-public'`), '10');

const out = sql(activateSql(pub)).split('\n');
assert.equal(out[0], out[2], 'current publications of other countries are identical before and after activation');
assert.equal(anon("select count(*) from regional_simulation_publications where location_id like 'US:%' and is_current"), '5');
assert.equal(anon("select string_agg(harvest_years::text, ',' order by harvest_years) from regional_simulation_publications where location_id='US:fips:19169' and plan_id='us_soy' and is_current"), '{2027},{2028}');
assert.equal(anon("select summary->'yield'->>'research_status' is not null from simulation_runs where location_id='US:fips:20191'"), 't');
assert.equal(anon(`select storage_prefix||'|'||runs||'|'||places from simulation_publication_batches where status='active'`), `${pub.prefix}|5|2`);
assert.equal(brazil(), before);

sql(rollbackSql(pub));
assert.equal(anon("select count(*) from regional_simulation_publications where location_id like 'US:%'"), '0');
assert.equal(counts(), '6,10,6,1', 'rollback deletes nothing');
assert.equal(brazil(), before);
assert.equal(anon("select count(*) from regional_simulation_publications where location_id like 'BR:%' and is_current"), '1');
console.log('publication tool SQL: all assertions passed');
